using System;
using System.Collections.Generic;
using System.Runtime.Serialization;

namespace EngiSentry.Intelligence
{
    public static class JevSemanticLabels { public const string AccessRoadEdge="ACCESS_ROAD_EDGE"; public const string SecurityFence="SECURITY_FENCE"; public const string UnitBoundary="UNIT_BOUNDARY"; public const string Unrelated="UNRELATED"; public const string Unknown="UNKNOWN"; public static readonly string[] All={AccessRoadEdge,SecurityFence,UnitBoundary,Unrelated,Unknown}; }
    public static class JevSemanticAdvisoryStates { public const string Classified="CLASSIFIED"; public const string NoAmbiguities="NO_AMBIGUITIES"; public const string Disabled="JEV_DISABLED"; public const string NotConfigured="JEV_NOT_CONFIGURED"; public const string Unavailable="JEV_UNAVAILABLE"; public const string InvalidResponse="INVALID_RESPONSE"; }
    [DataContract] public sealed class SemanticAmbiguityCase { [DataMember(Order=1)] public string EvidenceId {get;set;}=string.Empty; [DataMember(Order=2)] public string GeometryKind {get;set;}=string.Empty; [DataMember(Order=3,EmitDefaultValue=false)] public string? LayerName {get;set;} [DataMember(Order=4)] public string CurrentDeterministicState {get;set;}="Ambiguous"; [DataMember(Order=5)] public List<string> ExistingCandidateKinds {get;set;}=new List<string>(); [DataMember(Order=6)] public List<string> NearbyTextFragments {get;set;}=new List<string>(); [DataMember(Order=7)] public List<string> SpatialContext {get;set;}=new List<string>(); [DataMember(Order=8)] public List<string> MeasurementBasisHints {get;set;}=new List<string>(); }
    [DataContract] public sealed class JevChoiceProbability { [DataMember(Order=1)] public string Label {get;set;}=string.Empty; [DataMember(Order=2)] public double Probability {get;set;} }
    [DataContract] public sealed class JevSemanticAssistResult { [DataMember(Order=1)] public string EvidenceId {get;set;}=string.Empty; [DataMember(Order=2)] public string AdvisoryStatus {get;set;}=JevSemanticAdvisoryStates.NoAmbiguities; [DataMember(Order=3,EmitDefaultValue=false)] public string? Choice {get;set;} [DataMember(Order=4)] public List<JevChoiceProbability> ChoiceProbabilities {get;set;}=new List<JevChoiceProbability>(); [DataMember(Order=5)] public double? Confidence {get;set;} [DataMember(Order=6,EmitDefaultValue=false)] public string? Model {get;set;} [DataMember(Order=7,EmitDefaultValue=false)] public string? RequestId {get;set;} [DataMember(Order=8)] public long LatencyMilliseconds {get;set;} [DataMember(Order=9,EmitDefaultValue=false)] public string? ErrorCategory {get;set;} [DataMember(Order=10)] public string InputProjectionSha256 {get;set;}=string.Empty; }
    [DataContract] public sealed class JevSemanticAdvisorySidecar { [DataMember(Order=1)] public bool AdvisoryOnly {get;set;}=true; [DataMember(Order=2)] public bool DeterministicModelModified {get;set;} [DataMember(Order=3)] public bool GovernanceModified {get;set;} [DataMember(Order=4)] public bool RuleExecutionModified {get;set;} [DataMember(Order=5)] public bool PlacementProposalModified {get;set;} [DataMember(Order=6)] public bool DwgModified {get;set;} [DataMember(Order=7)] public List<JevSemanticAssistResult> Results {get;set;}=new List<JevSemanticAssistResult>(); }
    public sealed class JevSemanticAssistPolicy { public bool Enabled {get;private set;} public bool HasApiKey {get;private set;} public string? ApiKey {get;private set;} public static JevSemanticAssistPolicy FromEnvironment() { string? key=Environment.GetEnvironmentVariable("TYPESAFE_API_KEY"); return new JevSemanticAssistPolicy { Enabled=string.Equals(Environment.GetEnvironmentVariable("ENGISENTRY_JEV_ENABLED"),"1",StringComparison.Ordinal), HasApiKey=!string.IsNullOrWhiteSpace(key), ApiKey=key }; } public static JevSemanticAssistPolicy ForTests(bool enabled,bool hasKey) => new JevSemanticAssistPolicy { Enabled=enabled, HasApiKey=hasKey, ApiKey=hasKey?"test-only-not-a-secret":null }; }
}
